"Phonk":"Phonk",
"Techno intense":"Интенсивное техно",
"Techno puissante":"Мощное техно",
"🎬 Voir le tuto vidéo du carnet (1 min)":"🎬 Смотреть видеоурок по дневнику (1 мин)",
"Il n’y a encore rien à raconter : ajoute des souvenirs avec des photos et des lieux.":"Пока нечего рассказать: добавь воспоминания с фото и местами.",
"Ta route est visible des abonnés":"Твой маршрут виден подписчикам",
"Ta route est cachée aux abonnés":"Твой маршрут скрыт от подписчиков",
"Touche pour la cacher":"Нажми, чтобы скрыть",
"Touche pour la montrer sur leur carte":"Нажми, чтобы показать на их карте",
"La route du voyage":"Маршрут поездки",
"Route visible des abonnés":"Маршрут виден подписчикам",
"Route masquée aux abonnés":"Маршрут скрыт от подписчиков",
"Montrer ta route aux abonnés de ce voyage ?\n\nIls verront sur une carte le trajet enregistré par le suivi et ta dernière position (précision ≈ 100 m), avec l’heure.\nTu peux arrêter quand tu veux : la carte disparaît chez eux à la synchro suivante.\nTes compagnons choisissent chacun pour eux.":"Показать маршрут подписчикам этой поездки?\n\nОни увидят на карте путь, записанный трекингом, и твоё последнее местоположение (точность ≈ 100 м) со временем.\nТы можешь остановить это когда угодно: карта исчезнет у них при следующей синхронизации.\nКаждый попутчик решает сам за себя.",
"Publier « {0} » pour des abonnés ?\n\nIls verront uniquement les souvenirs : photos, titres, lieux et récits. Le programme, les réservations, le budget et les documents restent privés.\nUn souvenir marqué « privé » n’est jamais publié.\nIls voient les photos en vignettes (taille réduite).\nTa position n’est jamais montrée, sauf si chaque voyageur l’active lui-même dans le suivi du voyage.\nIls pourront mettre des ❤️ et des commentaires.":"Опубликовать «{0}» для подписчиков?\n\nОни увидят только воспоминания: фото, заголовки, места и рассказы. План, бронирования, бюджет и документы остаются личными.\nВоспоминание с пометкой «личное» никогда не публикуется.\nФото они видят в виде миниатюр (уменьшенный размер).\nТвоё местоположение никогда не показывается, если только каждый путешественник сам не включит его в трекинге поездки.\nОни смогут ставить ❤️ и писать комментарии.",
