"Le code d’un voyage permet à tes compagnons de le rejoindre (tout le voyage, pas seulement les photos).":"Код поездки позволяет попутчикам присоединиться к ней (ко всей поездке, а не только к фото).",
"Rien de nouveau depuis ta dernière visite.":"Ничего нового с твоего последнего визита.",
