"Facultatif : sauvegarde en ligne de tous tes voyages, pour les retrouver sur ton autre téléphone ou ta tablette avec le même code. Hors connexion, tout reste sur le téléphone et part dès que le réseau revient.":"Необязательно: онлайн-копия всех твоих поездок, чтобы найти их на другом телефоне или планшете с тем же кодом. Без сети всё остаётся на телефоне и отправляется, как только сеть вернётся.",
"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"Чтобы поделиться одной поездкой, это не нужно: в поездке нажми «Поделиться». Тогда на сервере хранится только эта поездка, остальные остаются на телефоне.",
