"🔑 Nouveau code (repartir à neuf)":"🔑 Новый код (начать заново)",
"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"Создать новый код для «{0}»?\n\nПоездка, её карточки и фото снова уйдут на сервер под новым кодом. Другим телефонам потом нужно присоединиться по новому коду (Мои поездки → Присоединиться к общей поездке).",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ Не удалось отправить поездку под новым кодом: {0}\nПопробуй ещё раз через «Отправить всё заново», когда связь будет хорошей.",
"✅ Voyage en ligne : le code peut être donné":"✅ Поездка в сети: кодом можно делиться",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"У этой поездки уже был код (например, удалённый с сервера)? Вставь его сюда, чтобы использовать снова: другие телефоны его найдут.\nИначе оставь пустым: будет создан новый код.",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 Удалено с сервера: карточек — {0}, фото — {1}.\nТвои данные остаются на этом телефоне.\n\nОставить код на этом телефоне?\nOK = оставить код: позже можно будет отправить всё заново с тем же кодом (кнопка «Отправить всё заново»).\nОтмена = забыть этот код здесь.",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"Код сохранён. Чтобы вернуть всё на сервер: {0} → «Отправить всё заново».",
"Mes voyages → le voyage → code":"Мои поездки → поездка → код",
"📤 Voyage ou photos non arrivés ?":"📤 Поездка или фото не дошли?",
"Renvoie vers le serveur toutes les fiches et toutes les photos de ce téléphone, par exemple après une suppression sur le serveur. Rien n’est dupliqué.":"Заново отправляет на сервер все карточки и фото с этого телефона, например после удаления данных с сервера. Ничего не дублируется.",
