"👀 3 voyages de démo sont prêts (rien n’est partagé) :\n\n📍 En cours : on est au jour 7 — traceur, steps, tickets, courses, plafond, parts inégales.\n🧳 Préparation : le même Japon dans 6 mois, à organiser.\n🗺️ Passés / 🏁 Bilan : le voyage terminé avec ses photos, son album et ses comptes.\n\nPasse d’un onglet à l’autre en haut de l’écran. « Supprimer la démo » efface tout.":"👀 Готовы 3 демо-поездки (ничего не публикуется):\n\n📍 Идёт: мы на 7-м дне — трекер, шаги, чеки, покупки, лимит, неравные доли.\n🧳 Подготовка: та же Япония через 6 месяцев, которую нужно организовать.\n🗺️ Прошедшие / 🏁 Итоги: завершённая поездка с фото, альбомом и расчётами.\n\nПереключайся между вкладками вверху экрана. «Удалить демо» стирает всё.",
"Supprimer le voyage de démo ?\n\nTes propres voyages ne sont pas touchés.":"Удалить демо-поездку?\n\nТвои собственные поездки не затрагиваются.",
"🗑 Démo supprimée":"🗑 Демо удалено",
