"Une fois l’appli en ligne sur Cloudflare (voir le LISEZMOI), vous utilisez le même code : ce que l’un modifie, l’autre le voit. Hors connexion, tout reste enregistré sur le téléphone et part dès que le réseau revient.":"Когда приложение будет в сети на Cloudflare (см. README), вы используете один и тот же код: что меняет один, видят остальные. Без сети всё сохраняется на телефоне и отправляется, как только сеть вернётся.",
