"Le carnet partagé contient déjà {0} fiches.\n\nOK = utiliser le carnet partagé (recommandé pour rejoindre : ce téléphone garde seulement ses profils).\nAnnuler = fusionner les deux carnets.":"В общем дневнике уже {0} карточек.\n\nOK = использовать общий дневник (рекомендуется при присоединении: этот телефон сохраняет только свои профили).\nОтмена = объединить два дневника.",
"☁️ Synchro activée":"☁️ Синхронизация включена",
"Désactiver la synchro sur ce téléphone ? Les données restent ici.":"Выключить синхронизацию на этом телефоне? Данные останутся здесь.",
"Rejoins notre carnet de voyage 🧳\n{0}\nCode du carnet : {1}\n(⚙️ Partage → colle le code → Activer la synchro)":"Присоединяйся к нашему путевому дневнику 🧳\n{0}\nКод дневника: {1}\n(⚙️ Доступ → вставь код → Включить синхронизацию)",
