"Le voyage 2027 existe déjà ici. Le remplacer par celui du fichier ?":"Поездка 2027 уже есть здесь. Заменить её той, что в файле?",
"Fichier illisible : ce n’est pas un export JSON valide.":"Нечитаемый файл: это не корректный экспорт JSON.",
"Le fichier contient aussi l’archive 2026. La restaurer ?":"В файле есть также архив 2026. Восстановить его?",
"Ce carnet n’est pas synchronisé : rien n’est stocké sur le serveur.":"Этот дневник не синхронизирован: на сервере ничего не хранится.",
"Demander l’effacement de ce carnet sur le serveur ?\n\nToutes ses données en ligne seront supprimées, pour TOUS ses membres. Un e-mail va être préparé : il contient seulement l’identifiant chiffré du carnet, jamais son code.":"Запросить удаление этого дневника с сервера?\n\nВсе его онлайн-данные будут удалены — для ВСЕХ участников. Будет подготовлено письмо: в нём только зашифрованный идентификатор дневника, но никогда не его код.",
"Les données restent sur le serveur partagé, tu pourras le rejoindre à nouveau avec le code.":"Данные остаются на общем сервере, ты сможешь снова присоединиться по коду.",
"Sans synchro, tout sera perdu : exporte avant !":"Без синхронизации всё будет потеряно: сначала сделай экспорт!",
