"🎬 La vidéo (3 min) montre tout le parcours sur un voyage fictif Paris → Tokyo : menu, passage en premium, dates, calendrier de prix, prix live, hôtels, voiture, activités, puis la saisie dans le carnet. Le détail écrit est juste en dessous.":"🎬 Видео (3 мин) показывает весь путь на вымышленной поездке Париж → Токио: меню, переход в премиум, даты, календарь цен, живые цены, отели, авто, развлечения, затем ввод в дневник. Текстовое описание — сразу ниже.",
"Escale cherche les vols les moins chers. En":"Escale ищет самые дешёвые рейсы. В",
"mode soft":"лёгком режиме",
