"Billet":"Билет",
"Colle ici le texte de la confirmation…":"Вставь сюда текст подтверждения…",
"📋 Coller une confirmation":"📋 Вставить подтверждение",
"Copie le texte de l’e-mail de réservation (vol, hôtel, train, bus…) et colle-le ici : l’appli repère la date, les horaires, la référence, la compagnie et le prix. Tu vérifies avant d’enregistrer. Rien n’est envoyé sur Internet.":"Скопируй текст письма о бронировании (рейс, отель, поезд, автобус…) и вставь сюда: приложение найдёт дату, время, номер брони, авиакомпанию и цену. Ты всё проверяешь перед сохранением. В интернет ничего не отправляется.",
"🔍 Analyser":"🔍 Разобрать",
"Colle le texte complet de la confirmation.":"Вставь полный текст подтверждения.",
"Ajoute des trajets avec un départ et une arrivée.":"Добавь переезды с точкой отправления и прибытия.",
"🌍 Empreinte et conseils":"🌍 След и советы",
