"par personne{0}":"на человека{0}",
"⏳ Un peu tôt : la fenêtre la plus souvent favorable est {0}–{1} semaines avant. Compare plusieurs dates sur les sites des compagnies.":"⏳ Немного рано: чаще всего выгодное окно — за {0}–{1} нед. Сравни несколько дат на сайтах авиакомпаний.",
"✅ Bonne période pour réserver ({0}–{1} semaines avant). Compare les prix sur les sites des compagnies.":"✅ Хорошее время для брони (за {0}–{1} нед.). Сравни цены на сайтах авиакомпаний.",
"⚠️ Départ proche : les prix montent souvent. Compare vite (dates voisines, aéroports proches).":"⚠️ Отъезд скоро: цены часто растут. Сравни поскорее (соседние даты, ближайшие аэропорты).",
