"par personne pour les trajets du voyage · repère : un aller-retour Paris–New York ≈ 1 t ; un Français émet ≈ 9 t par an":"на человека за переезды поездки · для сравнения: Париж–Нью-Йорк туда-обратно ≈ 1 т; француз выбрасывает ≈ 9 т в год",
"Ordres de grandeur (distance à vol d’oiseau corrigée × facteurs moyens type ADEME), pas un calcul certifié. Conseils de réservation = tendances générales, pas une prédiction de prix.":"Порядок величин (скорректированное расстояние по прямой × средние коэффициенты в духе ADEME), не сертифицированный расчёт. Советы по брони = общие тенденции, а не прогноз цен.",
