"Pays comptés pour les voyages commencés, d’après les villes des hébergements et tes « Je suis ici ». Distances à vol d’oiseau entre étapes.":"Страны считаются для начавшихся поездок — по городам жилья и твоим «Я здесь». Расстояния между остановками — по прямой.",
