"Itinéraire du voyage":"Маршрут поездки",
"Je suis ici":"Я здесь",
"Rien à exporter : ajoute des hébergements avec leur ville ou des lieux à voir.":"Нечего экспортировать: добавь жильё с городом или места для посещения.",
"Ajoute d’abord les hébergements (une ville par étape).":"Сначала добавь жильё (по городу на остановку).",
"Pour chaque étape, l’appli choisit les lieux les plus connus (Wikipédia, OpenStreetMap) et les répartit sur les jours, sans toucher à ce que tu as déjà prévu. Tu ajustes ensuite dans « Organiser l’étape ».":"Для каждой остановки приложение выбирает самые известные места (Википедия, OpenStreetMap) и распределяет их по дням, не трогая уже запланированное. Затем можно поправить в «Спланировать остановку».",
