"Activer le suivi du voyage ?\n\n• Ta position est enregistrée environ tous les 300 m, seulement quand l’appli est ouverte (une appli web ne peut pas suivre en arrière-plan, téléphone en poche).\n• Un point est aussi ajouté à chaque ouverture de l’appli.\n• La route est partagée uniquement avec les personnes de CE voyage.\n• Tu peux l’arrêter à tout moment.":"Включить отслеживание поездки?\n\n• Местоположение записывается примерно каждые 300 м, только пока приложение открыто (веб-приложение не умеет следить в фоне, когда телефон в кармане).\n• При каждом открытии приложения тоже добавляется точка.\n• Маршрут виден только участникам ЭТОЙ поездки.\n• Можно остановить в любой момент.",
