"Le globe n’a pas pu se charger. Vérifie ta connexion et réessaie.":"Не удалось загрузить глобус. Проверь подключение и попробуй снова.",
"Pour le survol, ajoute des souvenirs avec un lieu ou des hébergements avec une ville.":"Для облёта добавь воспоминания с местом или жильё с городом.",
"↺ Revoir":"↺ Смотреть снова",
"⏺ Enregistrer la vidéo":"⏺ Записать видео",
